insert into kairo.questions (id, subject, topic, subtopic, learning_objective, concepts_tested, difficulty_rating, cognitive_level, estimated_solving_time_sec, reading_load, calculation_load, distractors, source, year, exam_body, stem, options, correct_option, explanation, lifecycle_state, distractor_rationale) values
($q$chemistry_0288$q$, $q$Chemistry$q$, $q$Nature of Matter$q$, $q$Avogadro's Law$q$, $q$Answer a real JAMB 2001 question on Avogadro's Law.$q$, $q$[{"conceptId": "fb792s", "weight": 1}]$q$::jsonb, 2, $q$recall$q$, 37, $q$medium$q$, $q$light$q$, $q$[{"option": "A", "explanation": "Introduces a factor of 2 that has no basis in the question \u2014 nothing about the setup doubles the molecule count.", "misconceptionId": "guessed_no_reasoning"}, {"option": "B", "explanation": "Same unjustified doubling, plus keeps the wrong variable (Z rather than a molecule-count answer expressed in the gas's own terms).", "misconceptionId": "guessed_no_reasoning"}, {"option": "C", "explanation": "Answers with 'Y' as if it were a molecule count, confusing the gas's label with the actual number of molecules being asked about.", "misconceptionId": "misunderstood_terminology"}]$q$::jsonb, $q$jamb_past_question$q$, 2001, $q$JAMB$q$, $q$25cm3 of a gas X contains Z molecules at 15oC and 75 mm Hg. How many molecules will 25cm3 of another gas Y contain at the same temperature and pressure?$q$, $q$[{"label": "A", "text": "2Y", "isCorrect": false}, {"label": "B", "text": "2Z", "isCorrect": false}, {"label": "C", "text": "Y", "isCorrect": false}, {"label": "D", "text": "Z", "isCorrect": true}]$q$::jsonb, $q$D$q$, $q$This is Avogadro's law in its purest form: equal volumes of any gas, at the same temperature and pressure, contain equal numbers of molecules — regardless of what the gas actually is. Same volume, same T, same P, means same molecule count. Y's identity is irrelevant here.$q$, $q$live$q$, $q$A: Introduces a factor of 2 that has no basis in the question — nothing about the setup doubles the molecule count. B: Same unjustified doubling, plus keeps the wrong variable (Z rather than a molecule-count answer expressed in the gas's own terms). C: Answers with 'Y' as if it were a molecule count, confusing the gas's label with the actual number of molecules being asked about.$q$),
($q$chemistry_0289$q$, $q$Chemistry$q$, $q$Chemical Combination$q$, $q$Mass-Mass Stoichiometry$q$, $q$Answer a real JAMB 2001 question on Mass-Mass Stoichiometry.$q$, $q$[{"conceptId": "e5q9c8", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 57, $q$low$q$, $q$light$q$, $q$[{"option": "B", "explanation": "Half the correct answer \u2014 likely from treating the H2-to-H2O ratio as 2:1 instead of the correct 1:1.", "misconceptionId": "formula_recall_error"}, {"option": "C", "explanation": "Uses the molar mass of water (18) but appears to have skipped the mole-ratio scaling by the actual moles of H2 present.", "misconceptionId": "arithmetic_slip"}, {"option": "D", "explanation": "Simply restates the given mass of hydrogen without doing any stoichiometric conversion at all.", "misconceptionId": "guessed_no_reasoning"}]$q$::jsonb, $q$jamb_past_question$q$, 2001, $q$JAMB$q$, $q$What mass of water is produced when 8.0g of hydrogen reacts with excess oxygen?$q$, $q$[{"label": "A", "text": "72.0g", "isCorrect": true}, {"label": "B", "text": "36.0g", "isCorrect": false}, {"label": "C", "text": "16.0g", "isCorrect": false}, {"label": "D", "text": "8.0g", "isCorrect": false}]$q$::jsonb, $q$A$q$, $q$2H2 + O2 → 2H2O — the mole ratio of H2 to H2O is 1:1. Moles of H2 = 8.0/2 = 4 mol, so 4 mol of H2O forms. Mass of water = 4 × 18 = 72.0g.$q$, $q$live$q$, $q$B: Half the correct answer — likely from treating the H2-to-H2O ratio as 2:1 instead of the correct 1:1. C: Uses the molar mass of water (18) but appears to have skipped the mole-ratio scaling by the actual moles of H2 present. D: Simply restates the given mass of hydrogen without doing any stoichiometric conversion at all.$q$),
($q$chemistry_0290$q$, $q$Chemistry$q$, $q$Atomic Structure & Bonding$q$, $q$Metals vs Non-Metals — Periodic Position$q$, $q$Answer a real JAMB 2001 question on Metals vs Non-Metals — Periodic Position.$q$, $q$[{"conceptId": "f0dj68", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 57, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "Carbon (Z=6) is a non-metal \u2014 this picks the element without checking where atomic number 6 actually sits on the periodic table.", "misconceptionId": "memorized_not_understood"}, {"option": "C", "explanation": "Helium (Z=2) is a noble gas, about as far from being a metal as an element can get.", "misconceptionId": "memorized_not_understood"}, {"option": "D", "explanation": "Sulphur (Z=16) is a non-metal \u2014 easy to miss if you're not actually placing the atomic number on the table.", "misconceptionId": "memorized_not_understood"}]$q$::jsonb, $q$jamb_past_question$q$, 2001, $q$JAMB$q$, $q$Four elements W, X, Y and Z have atomic numbers 2, 6, 16 and 20 respectively. Which of these elements is a metal?$q$, $q$[{"label": "A", "text": "X", "isCorrect": false}, {"label": "B", "text": "Z", "isCorrect": true}, {"label": "C", "text": "W", "isCorrect": false}, {"label": "D", "text": "Y", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$Place each atomic number on the periodic table: W (2) is helium, a noble gas. X (6) is carbon, a non-metal. Y (16) is sulphur, a non-metal. Z (20) is calcium, a genuine metal — a reactive group 2 element. Only Z fits.$q$, $q$live$q$, $q$A: Carbon (Z=6) is a non-metal — this picks the element without checking where atomic number 6 actually sits on the periodic table. C: Helium (Z=2) is a noble gas, about as far from being a metal as an element can get. D: Sulphur (Z=16) is a non-metal — easy to miss if you're not actually placing the atomic number on the table.$q$),
($q$chemistry_0291$q$, $q$Chemistry$q$, $q$Atomic Structure & Bonding$q$, $q$Isotopic Abundance Calculations$q$, $q$Answer a real JAMB 2001 question on Isotopic Abundance Calculations.$q$, $q$[{"conceptId": "gzi1bc", "weight": 1}]$q$::jsonb, 3, $q$application$q$, 69, $q$medium$q$, $q$light$q$, $q$[{"option": "A", "explanation": "Likely comes from subtracting rather than solving the weighted-average equation properly \u2014 16.2 minus 16 times some factor, without setting up the full equation.", "misconceptionId": "formula_recall_error"}, {"option": "B", "explanation": "Another value that doesn't emerge from correctly solving the weighted-average equation \u2014 possibly from an arithmetic slip partway through.", "misconceptionId": "arithmetic_slip"}, {"option": "D", "explanation": "Just repeats the known isotope's mass number (16) rather than solving for the unknown one \u2014 a sign the equation was never actually set up.", "misconceptionId": "guessed_no_reasoning"}]$q$::jsonb, $q$jamb_past_question$q$, 2001, $q$JAMB$q$, $q$An element X with relative atomic mass 16.2 contains two isotopes, 16-X with relative abundance of 90% and m-X with relative abundance of 10%. The value of m is$q$, $q$[{"label": "A", "text": "14", "isCorrect": false}, {"label": "B", "text": "12", "isCorrect": false}, {"label": "C", "text": "18", "isCorrect": true}, {"label": "D", "text": "16", "isCorrect": false}]$q$::jsonb, $q$C$q$, $q$The relative atomic mass is a weighted average: 16.2 = (0.90 × 16) + (0.10 × m). That gives 16.2 = 14.4 + 0.1m, so 0.1m = 1.8, and m = 18.$q$, $q$live$q$, $q$A: Likely comes from subtracting rather than solving the weighted-average equation properly — 16.2 minus 16 times some factor, without setting up the full equation. B: Another value that doesn't emerge from correctly solving the weighted-average equation — possibly from an arithmetic slip partway through. D: Just repeats the known isotope's mass number (16) rather than solving for the unknown one — a sign the equation was never actually set up.$q$),
($q$chemistry_0292$q$, $q$Chemistry$q$, $q$Atomic Structure & Bonding$q$, $q$Radioactivity and Half-Life$q$, $q$Answer a real JAMB 2001 question on Radioactivity and Half-Life.$q$, $q$[{"conceptId": "ot0voy", "weight": 1}]$q$::jsonb, 1, $q$recall$q$, 25, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "X-rays are mainly associated with diagnostic imaging, not the standard curative radiotherapy this question is pointing at.", "misconceptionId": "confused_similar_concepts"}, {"option": "B", "explanation": "Beta rays have much lower penetrating power than gamma rays and aren't the standard radiotherapy source for internal tumours.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "Alpha particles barely penetrate skin at all \u2014 completely unsuitable for reaching an internal tumour from outside the body.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2001, $q$JAMB$q$, $q$Cancerous growth are cured by exposure to$q$, $q$[{"label": "A", "text": "x-rays", "isCorrect": false}, {"label": "B", "text": "beta-rays", "isCorrect": false}, {"label": "C", "text": "alpha-rays", "isCorrect": false}, {"label": "D", "text": "gamma-rays", "isCorrect": true}]$q$::jsonb, $q$D$q$, $q$Gamma rays are the standard radiation used in cancer radiotherapy (cobalt-60 is a classic gamma source) — they penetrate deeply enough to reach internal tumours while damaging the rapidly-dividing cancer cells.$q$, $q$live$q$, $q$A: X-rays are mainly associated with diagnostic imaging, not the standard curative radiotherapy this question is pointing at. B: Beta rays have much lower penetrating power than gamma rays and aren't the standard radiotherapy source for internal tumours. C: Alpha particles barely penetrate skin at all — completely unsuitable for reaching an internal tumour from outside the body.$q$),
($q$chemistry_0293$q$, $q$Chemistry$q$, $q$Kinetic Theory & Gas Laws$q$, $q$Kinetic Theory — Temperature and Energy$q$, $q$Answer a real JAMB 2001 question on Kinetic Theory — Temperature and Energy.$q$, $q$[{"conceptId": "v89sra", "weight": 1}]$q$::jsonb, 1, $q$recall$q$, 25, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "Confuses pressure (a consequence of molecular collisions with the container) with the underlying cause (kinetic energy, which depends on temperature).", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "Volume changes don't directly affect kinetic energy \u2014 you can change a gas's volume at constant temperature without altering its average kinetic energy at all.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "'At constant pressure' doesn't say anything about what's actually changing \u2014 kinetic energy still depends on temperature, not on holding pressure fixed.", "misconceptionId": "misunderstood_terminology"}]$q$::jsonb, $q$jamb_past_question$q$, 2001, $q$JAMB$q$, $q$Which of the following statements is correct about the average kinetic energy of the molecules of a gas?$q$, $q$[{"label": "A", "text": "it increases with increase in pressure", "isCorrect": false}, {"label": "B", "text": "it increases with increase in temperature", "isCorrect": true}, {"label": "C", "text": "it increases with increase in volume", "isCorrect": false}, {"label": "D", "text": "it increases at constant pressure", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$Kinetic theory ties average kinetic energy directly to temperature and only temperature — it's essentially the definition of what temperature measures at the molecular level. Pressure and volume can change independently of kinetic energy (think of Boyle's law, done at constant temperature).$q$, $q$live$q$, $q$A: Confuses pressure (a consequence of molecular collisions with the container) with the underlying cause (kinetic energy, which depends on temperature). C: Volume changes don't directly affect kinetic energy — you can change a gas's volume at constant temperature without altering its average kinetic energy at all. D: 'At constant pressure' doesn't say anything about what's actually changing — kinetic energy still depends on temperature, not on holding pressure fixed.$q$),
($q$chemistry_0294$q$, $q$Chemistry$q$, $q$Atomic Structure & Bonding$q$, $q$History of Atomic Theory$q$, $q$Answer a real JAMB 2001 question on History of Atomic Theory.$q$, $q$[{"conceptId": "nucy3t", "weight": 1}]$q$::jsonb, 2, $q$recall$q$, 37, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "Positive rays are associated with Goldstein's work, not Millikan's.", "misconceptionId": "confused_similar_concepts"}, {"option": "B", "explanation": "Cathode rays are associated with earlier work (Crookes, Thomson), not Millikan's specific contribution.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "The charge-to-mass ratio of the electron is Thomson's result, not Millikan's \u2014 Millikan's follow-up work found the charge alone, which then let scientists calculate the electron's mass.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2001, $q$JAMB$q$, $q$Millikan's contribution to the development of atomic theory is the determination of$q$, $q$[{"label": "A", "text": "positive rays", "isCorrect": false}, {"label": "B", "text": "cathode rays", "isCorrect": false}, {"label": "C", "text": "charge to mass ratio", "isCorrect": false}, {"label": "D", "text": "charge on electron", "isCorrect": true}]$q$::jsonb, $q$D$q$, $q$Millikan's famous oil-drop experiment measured the precise charge carried by a single electron. Keep the scientists straight: Thomson discovered the electron and measured its charge-to-mass ratio, Millikan pinned down its actual charge.$q$, $q$live$q$, $q$A: Positive rays are associated with Goldstein's work, not Millikan's. B: Cathode rays are associated with earlier work (Crookes, Thomson), not Millikan's specific contribution. C: The charge-to-mass ratio of the electron is Thomson's result, not Millikan's — Millikan's follow-up work found the charge alone, which then let scientists calculate the electron's mass.$q$),
($q$chemistry_0295$q$, $q$Chemistry$q$, $q$Atomic Structure & Bonding$q$, $q$Subatomic Particles and Ion Charge$q$, $q$Answer a real JAMB 2001 question on Subatomic Particles and Ion Charge.$q$, $q$[{"conceptId": "f4y1pg", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 57, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "Gets the charge backwards \u2014 more electrons than protons gives a negative charge, not a positive one.", "misconceptionId": "sign_error"}, {"option": "B", "explanation": "Fluorine (9 protons) is a non-metal, not a metal \u2014 and the unequal proton/electron count means it isn't neutral either.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "Correctly identifies fluorine as a non-metal but misses that the electron count doesn't match the proton count, so this can't be a neutral atom.", "misconceptionId": "misread_graph"}]$q$::jsonb, $q$jamb_past_question$q$, 2001, $q$JAMB$q$, $q$A particle that contains 9 protons, 10 neutrons and 10 electrons is$q$, $q$[{"label": "A", "text": "positive ion", "isCorrect": false}, {"label": "B", "text": "neutral atom of a metal", "isCorrect": false}, {"label": "C", "text": "neutral atom of a non-metal", "isCorrect": false}, {"label": "D", "text": "negative ion", "isCorrect": true}]$q$::jsonb, $q$D$q$, $q$9 protons identifies the element as fluorine. A neutral fluorine atom would have 9 electrons to match its 9 protons — but this particle has 10 electrons, one more than protons, giving it an overall negative charge. That extra electron makes it F-, a negative ion, and fluorine is a non-metal that commonly forms anions this way.$q$, $q$live$q$, $q$A: Gets the charge backwards — more electrons than protons gives a negative charge, not a positive one. B: Fluorine (9 protons) is a non-metal, not a metal — and the unequal proton/electron count means it isn't neutral either. C: Correctly identifies fluorine as a non-metal but misses that the electron count doesn't match the proton count, so this can't be a neutral atom.$q$),
($q$chemistry_0296$q$, $q$Chemistry$q$, $q$Chemical Combination$q$, $q$Vapour Density and Molar Mass$q$, $q$Answer a real JAMB 2001 question on Vapour Density and Molar Mass.$q$, $q$[{"conceptId": "m4b114", "weight": 1}]$q$::jsonb, 3, $q$application$q$, 69, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "Doesn't match a clean derivation from the vapour density relationship \u2014 likely from skipping the \u00d72 step in converting vapour density to molar mass.", "misconceptionId": "formula_recall_error"}, {"option": "C", "explanation": "This is nitrogen's atomic mass \u2014 a plausible-sounding number that doesn't come from actually solving the equation given.", "misconceptionId": "guessed_no_reasoning"}, {"option": "D", "explanation": "This is carbon's atomic mass \u2014 again, a familiar number rather than the result of the calculation.", "misconceptionId": "guessed_no_reasoning"}]$q$::jsonb, $q$jamb_past_question$q$, 2001, $q$JAMB$q$, $q$An oxide XO2 has a vapour density of 32. What is the atomic mass of X?$q$, $q$[{"label": "A", "text": "20", "isCorrect": false}, {"label": "B", "text": "32", "isCorrect": true}, {"label": "C", "text": "14", "isCorrect": false}, {"label": "D", "text": "12", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$Molar mass = 2 × vapour density = 2 × 32 = 64. XO2's molar mass is X + 2(16) = X + 32. Setting that equal to 64: X = 64 - 32 = 32.$q$, $q$live$q$, $q$A: Doesn't match a clean derivation from the vapour density relationship — likely from skipping the ×2 step in converting vapour density to molar mass. C: This is nitrogen's atomic mass — a plausible-sounding number that doesn't come from actually solving the equation given. D: This is carbon's atomic mass — again, a familiar number rather than the result of the calculation.$q$),
($q$chemistry_0297$q$, $q$Chemistry$q$, $q$Air and Water$q$, $q$Water Treatment and Hardness$q$, $q$Answer a real JAMB 2001 question on Water Treatment and Hardness.$q$, $q$[{"conceptId": "beypy2", "weight": 1}]$q$::jsonb, 2, $q$recall$q$, 37, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "Copper sulphate has other water-treatment uses (like controlling algae) but isn't the standard coagulant.", "misconceptionId": "confused_similar_concepts"}, {"option": "B", "explanation": "Sodium sulphate has no coagulating action \u2014 sodium ions don't neutralize particle charge the way aluminium's higher charge does.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "Calcium sulphate isn't used as a coagulant in water treatment \u2014 this substitutes a different, unrelated sulphate salt.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2001, $q$JAMB$q$, $q$The chemical used for coagulation in water purification is$q$, $q$[{"label": "A", "text": "copper tetraoxosulphate (VI)", "isCorrect": false}, {"label": "B", "text": "sodium tetraoxosulphate (VI)", "isCorrect": false}, {"label": "C", "text": "aluminium tetraoxosulphate (VI)", "isCorrect": true}, {"label": "D", "text": "calcium tetraoxosulphate (VI)", "isCorrect": false}]$q$::jsonb, $q$C$q$, $q$Aluminium sulphate (alum) is the classic coagulant used in water treatment — the aluminium ions neutralize the charge on suspended particles, letting them clump together and settle out. None of the other metal sulphates listed do this job in standard water treatment.$q$, $q$live$q$, $q$A: Copper sulphate has other water-treatment uses (like controlling algae) but isn't the standard coagulant. B: Sodium sulphate has no coagulating action — sodium ions don't neutralize particle charge the way aluminium's higher charge does. D: Calcium sulphate isn't used as a coagulant in water treatment — this substitutes a different, unrelated sulphate salt.$q$),
($q$chemistry_0298$q$, $q$Chemistry$q$, $q$Environmental Pollution$q$, $q$Vehicle Emissions and Heavy Metal Pollution$q$, $q$Answer a real JAMB 2001 question on Vehicle Emissions and Heavy Metal Pollution.$q$, $q$[{"conceptId": "u8nzau", "weight": 1}]$q$::jsonb, 2, $q$recall$q$, 37, $q$low$q$, $q$none$q$, $q$[{"option": "B", "explanation": "Water vapour is a normal, harmless combustion product \u2014 not a pollutant in the sense this question is testing.", "misconceptionId": "misunderstood_terminology"}, {"option": "C", "explanation": "Smoke is a visible nuisance but the question is pointing at the more specifically damaging heavy-metal content, not general particulate smoke.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "Same issue as water vapour \u2014 steam isn't a meaningful pollutant on its own.", "misconceptionId": "misunderstood_terminology"}]$q$::jsonb, $q$jamb_past_question$q$, 2001, $q$JAMB$q$, $q$Environmental pollution is worsened by the release from automobile exhausts of$q$, $q$[{"label": "A", "text": "heavy metals", "isCorrect": true}, {"label": "B", "text": "water vapour", "isCorrect": false}, {"label": "C", "text": "smoke", "isCorrect": false}, {"label": "D", "text": "steam", "isCorrect": false}]$q$::jsonb, $q$A$q$, $q$Heavy metals (historically lead, from leaded petrol additives) released in vehicle exhaust are the pollutant with the most serious, lasting environmental and health impact among the options — they don't break down and accumulate in the environment. Water vapour and steam are essentially harmless combustion byproducts.$q$, $q$live$q$, $q$B: Water vapour is a normal, harmless combustion product — not a pollutant in the sense this question is testing. C: Smoke is a visible nuisance but the question is pointing at the more specifically damaging heavy-metal content, not general particulate smoke. D: Same issue as water vapour — steam isn't a meaningful pollutant on its own.$q$),
($q$chemistry_0299$q$, $q$Chemistry$q$, $q$Non-Metals & Their Compounds$q$, $q$Reactivity and Storage of Elements$q$, $q$Answer a real JAMB 2001 question on Reactivity and Storage of Elements.$q$, $q$[{"conceptId": "vejcxc", "weight": 1}]$q$::jsonb, 2, $q$recall$q$, 37, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "Smell isn't the safety concern being addressed here \u2014 spontaneous combustion is.", "misconceptionId": "misunderstood_terminology"}, {"option": "B", "explanation": "Phosphorus isn't at risk of 'dehydrating' \u2014 that's not a meaningful concept for a solid element.", "misconceptionId": "misunderstood_terminology"}, {"option": "D", "explanation": "Storing phosphorus under water doesn't make it inert \u2014 it's still reactive, just protected from air. If anything, becoming 'inert' would remove the need for the precaution entirely, the opposite of the real reason.", "misconceptionId": "misunderstood_terminology"}]$q$::jsonb, $q$jamb_past_question$q$, 2001, $q$JAMB$q$, $q$Phosphorus is stored under water to prevent it from$q$, $q$[{"label": "A", "text": "smelling", "isCorrect": false}, {"label": "B", "text": "dehydrating", "isCorrect": false}, {"label": "C", "text": "catching fire", "isCorrect": true}, {"label": "D", "text": "becoming inert", "isCorrect": false}]$q$::jsonb, $q$C$q$, $q$White phosphorus is pyrophoric — it spontaneously ignites in contact with air at room temperature. Storing it under water cuts off its access to oxygen, which is the whole reason for the precaution.$q$, $q$live$q$, $q$A: Smell isn't the safety concern being addressed here — spontaneous combustion is. B: Phosphorus isn't at risk of 'dehydrating' — that's not a meaningful concept for a solid element. D: Storing phosphorus under water doesn't make it inert — it's still reactive, just protected from air. If anything, becoming 'inert' would remove the need for the precaution entirely, the opposite of the real reason.$q$),
($q$chemistry_0300$q$, $q$Chemistry$q$, $q$Separation of Mixtures$q$, $q$Separation Techniques$q$, $q$Answer a real JAMB 2001 question on Separation Techniques.$q$, $q$[{"conceptId": "kc1jua", "weight": 1}]$q$::jsonb, 1, $q$recall$q$, 25, $q$low$q$, $q$none$q$, $q$[{"option": "A", "explanation": "Evaporation gets rid of the solvent to leave the dissolved solid behind \u2014 it doesn't collect the solvent itself, so it can't be how you'd 'obtain' the pure solvent.", "misconceptionId": "confused_similar_concepts"}, {"option": "B", "explanation": "Extraction separates a substance from a mixture using a solvent, but doesn't purify the solvent itself.", "misconceptionId": "confused_similar_concepts"}, {"option": "C", "explanation": "Condensation is only one half of the distillation process (vaporize, then condense) \u2014 on its own it isn't the complete purification method being asked about.", "misconceptionId": "confused_similar_concepts"}]$q$::jsonb, $q$jamb_past_question$q$, 2001, $q$JAMB$q$, $q$Pure solvents are obtained by$q$, $q$[{"label": "A", "text": "evaporation", "isCorrect": false}, {"label": "B", "text": "extraction", "isCorrect": false}, {"label": "C", "text": "condensation", "isCorrect": false}, {"label": "D", "text": "distillation", "isCorrect": true}]$q$::jsonb, $q$D$q$, $q$Distillation is the standard method to recover a pure solvent from a solution — evaporation drives off the solvent and loses it, while distillation vaporizes and then condenses it back into a pure, collected liquid.$q$, $q$live$q$, $q$A: Evaporation gets rid of the solvent to leave the dissolved solid behind — it doesn't collect the solvent itself, so it can't be how you'd 'obtain' the pure solvent. B: Extraction separates a substance from a mixture using a solvent, but doesn't purify the solvent itself. C: Condensation is only one half of the distillation process (vaporize, then condense) — on its own it isn't the complete purification method being asked about.$q$),
($q$chemistry_0301$q$, $q$Chemistry$q$, $q$Nature of Matter$q$, $q$Deliquescent and Hygroscopic Substances$q$, $q$Answer a real JAMB 2001 question on Deliquescent and Hygroscopic Substances.$q$, $q$[{"conceptId": "syb7rg", "weight": 1}]$q$::jsonb, 2, $q$recall$q$, 37, $q$low$q$, $q$none$q$, $q$[{"option": "B", "explanation": "Deliquescence has nothing to do with melting \u2014 it's about moisture absorption, not a change of state from heat.", "misconceptionId": "misunderstood_terminology"}, {"option": "C", "explanation": "This gets the direction backwards \u2014 deliquescent substances absorb water rather than being used to add water to something else.", "misconceptionId": "sign_error"}, {"option": "D", "explanation": "Moisture absorption isn't a cooling process \u2014 this confuses the property with an unrelated physical effect.", "misconceptionId": "misunderstood_terminology"}]$q$::jsonb, $q$jamb_past_question$q$, 2001, $q$JAMB$q$, $q$Deliquescent substances are used for$q$, $q$[{"label": "A", "text": "drying", "isCorrect": true}, {"label": "B", "text": "melting", "isCorrect": false}, {"label": "C", "text": "wetting", "isCorrect": false}, {"label": "D", "text": "cooling", "isCorrect": false}]$q$::jsonb, $q$A$q$, $q$Deliquescent substances (like anhydrous calcium chloride) absorb moisture from the air so avidly they eventually dissolve into a solution of their own absorbed water — which is exactly what makes them useful as drying agents, pulling moisture out of a gas or an enclosed space.$q$, $q$live$q$, $q$B: Deliquescence has nothing to do with melting — it's about moisture absorption, not a change of state from heat. C: This gets the direction backwards — deliquescent substances absorb water rather than being used to add water to something else. D: Moisture absorption isn't a cooling process — this confuses the property with an unrelated physical effect.$q$),
($q$chemistry_0302$q$, $q$Chemistry$q$, $q$Air and Water$q$, $q$Oxygen Content of Air — Pyrogallol Absorption$q$, $q$Answer a real JAMB 2001 question on Oxygen Content of Air — Pyrogallol Absorption.$q$, $q$[{"conceptId": "txr2h3", "weight": 1}]$q$::jsonb, 3, $q$application$q$, 69, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "An order-of-magnitude-too-small answer, likely from a decimal-place slip when estimating oxygen's fraction of the air sample.", "misconceptionId": "arithmetic_slip"}, {"option": "B", "explanation": "Even further off in magnitude than option A \u2014 the same kind of decimal error compounded.", "misconceptionId": "arithmetic_slip"}, {"option": "C", "explanation": "Overestimates oxygen's share of air as roughly half (15/30), rather than the correct roughly one-fifth.", "misconceptionId": "memorized_not_understood"}]$q$::jsonb, $q$jamb_past_question$q$, 2001, $q$JAMB$q$, $q$What is the decrease in volume of air when pyrogallol is shaken with 30.00cm3 of air?$q$, $q$[{"label": "A", "text": "0.63cm3", "isCorrect": false}, {"label": "B", "text": "0.06cm3", "isCorrect": false}, {"label": "C", "text": "15.00cm3", "isCorrect": false}, {"label": "D", "text": "6.30cm3", "isCorrect": true}]$q$::jsonb, $q$D$q$, $q$Alkaline pyrogallol is a classic reagent that absorbs oxygen specifically out of a sample of air, leaving the rest (mostly nitrogen) behind. Oxygen makes up close to a fifth of air by volume, so the volume decrease should be roughly a fifth of 30cm3 — about 6cm3, matching 6.30cm3 here. This is worth remembering as a real lab technique for measuring the oxygen percentage in air, not just a number to memorize.$q$, $q$live$q$, $q$A: An order-of-magnitude-too-small answer, likely from a decimal-place slip when estimating oxygen's fraction of the air sample. B: Even further off in magnitude than option A — the same kind of decimal error compounded. C: Overestimates oxygen's share of air as roughly half (15/30), rather than the correct roughly one-fifth.$q$),
($q$chemistry_0303$q$, $q$Chemistry$q$, $q$Environmental Pollution$q$, $q$Pollution Control$q$, $q$Answer a real JAMB 2001 question on Pollution Control.$q$, $q$[{"conceptId": "alfbvy", "weight": 1}]$q$::jsonb, 2, $q$application$q$, 57, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "Ship traffic doesn't disperse oil in any controlled or useful way \u2014 if anything it can spread a slick further without breaking it down.", "misconceptionId": "guessed_no_reasoning"}, {"option": "C", "explanation": "Adding more organic solvent just adds another pollutant to the water rather than genuinely dispersing the oil.", "misconceptionId": "confused_similar_concepts"}, {"option": "D", "explanation": "Oil doesn't meaningfully evaporate off open water on any practical timescale \u2014 this isn't a real cleanup method.", "misconceptionId": "misunderstood_terminology"}]$q$::jsonb, $q$jamb_past_question$q$, 2001, $q$JAMB$q$, $q$The pollution from petroleum spillage in rivers and lakes can best be dispersed by$q$, $q$[{"label": "A", "text": "passing of ships through the area", "isCorrect": false}, {"label": "B", "text": "pouring detergents", "isCorrect": true}, {"label": "C", "text": "pouring organic solvents", "isCorrect": false}, {"label": "D", "text": "evaporation", "isCorrect": false}]$q$::jsonb, $q$B$q$, $q$Detergents act as surfactants, breaking an oil slick into fine droplets that disperse through the water rather than sitting on top — this is the standard method used on real oil spills, not just a textbook answer.$q$, $q$live$q$, $q$A: Ship traffic doesn't disperse oil in any controlled or useful way — if anything it can spread a slick further without breaking it down. C: Adding more organic solvent just adds another pollutant to the water rather than genuinely dispersing the oil. D: Oil doesn't meaningfully evaporate off open water on any practical timescale — this isn't a real cleanup method.$q$),
($q$chemistry_0304$q$, $q$Chemistry$q$, $q$Oxidation & Reduction$q$, $q$Oxidizing and Reducing Agents$q$, $q$Answer a real JAMB 2001 question on Oxidizing and Reducing Agents.$q$, $q$[{"conceptId": "0wt48x", "weight": 1}]$q$::jsonb, 3, $q$analysis$q$, 84, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "Copper isn't acting as a base here \u2014 this reaction is a redox reaction, not an acid-base one; copper is a metal reacting with an acid, not neutralizing it in the classical sense.", "misconceptionId": "misunderstood_terminology"}, {"option": "B", "explanation": "Gets the role backwards \u2014 copper is being oxidized (losing electrons), which makes it the reducing agent, not the oxidizing agent.", "misconceptionId": "sign_error"}, {"option": "D", "explanation": "Also backwards \u2014 copper is losing electrons (donating them), not accepting them, so it's an electron donor, not an acceptor.", "misconceptionId": "sign_error"}]$q$::jsonb, $q$jamb_past_question$q$, 2001, $q$JAMB$q$, $q$3Cu(s) + 8HNO3(aq) → 3Cu(NO3)2(aq) + 4H2O(l) + 2NO(g). In the equation above, copper is$q$, $q$[{"label": "A", "text": "a base", "isCorrect": false}, {"label": "B", "text": "an oxidizing agent", "isCorrect": false}, {"label": "C", "text": "a reducing agent", "isCorrect": true}, {"label": "D", "text": "an electron acceptor", "isCorrect": false}]$q$::jsonb, $q$C$q$, $q$Copper goes from 0 (elemental metal) to +2 (in Cu(NO3)2) — it's losing electrons, which means it's being oxidized. A substance that gets oxidized itself is, by definition, the reducing agent — it reduces something else (here, nitrogen in HNO3 goes from +5 to +2 in NO) by donating those electrons.$q$, $q$live$q$, $q$A: Copper isn't acting as a base here — this reaction is a redox reaction, not an acid-base one; copper is a metal reacting with an acid, not neutralizing it in the classical sense. B: Gets the role backwards — copper is being oxidized (losing electrons), which makes it the reducing agent, not the oxidizing agent. D: Also backwards — copper is losing electrons (donating them), not accepting them, so it's an electron donor, not an acceptor.$q$),
($q$chemistry_0305$q$, $q$Chemistry$q$, $q$Energy Changes$q$, $q$Entropy and Disorder$q$, $q$Answer a real JAMB 2001 question on Entropy and Disorder.$q$, $q$[{"conceptId": "s55vck", "weight": 1}]$q$::jsonb, 3, $q$analysis$q$, 84, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "A change this dramatic \u2014 two gases collapsing into one ordered solid \u2014 is never entropy-neutral; something has clearly changed in the system's disorder.", "misconceptionId": "misunderstood_terminology"}, {"option": "B", "explanation": "The direction is actually very determinable here from the states of matter alone \u2014 gas-to-solid is a clear, predictable decrease in disorder.", "misconceptionId": "guessed_no_reasoning"}, {"option": "C", "explanation": "Mixes up the general rule that reactions producing MORE gas molecules have positive entropy \u2014 here, gas molecules are being consumed to form a solid, the opposite direction.", "misconceptionId": "overgeneralized_rule"}]$q$::jsonb, $q$jamb_past_question$q$, 2001, $q$JAMB$q$, $q$NH3(g) + HCl(g) → NH4Cl(s). The entropy change in the system above is$q$, $q$[{"label": "A", "text": "zero", "isCorrect": false}, {"label": "B", "text": "indeterminate", "isCorrect": false}, {"label": "C", "text": "positive", "isCorrect": false}, {"label": "D", "text": "negative", "isCorrect": true}]$q$::jsonb, $q$D$q$, $q$Two gas molecules combine into one solid — that's a dramatic decrease in disorder. Gas particles move freely and independently; a solid locks them into a fixed, ordered lattice. Fewer options for how the particles can be arranged means entropy has decreased, so ΔS is negative.$q$, $q$live$q$, $q$A: A change this dramatic — two gases collapsing into one ordered solid — is never entropy-neutral; something has clearly changed in the system's disorder. B: The direction is actually very determinable here from the states of matter alone — gas-to-solid is a clear, predictable decrease in disorder. C: Mixes up the general rule that reactions producing MORE gas molecules have positive entropy — here, gas molecules are being consumed to form a solid, the opposite direction.$q$),
($q$chemistry_0306$q$, $q$Chemistry$q$, $q$Electrolysis$q$, $q$Faraday's Laws$q$, $q$Answer a real JAMB 2001 question on Faraday's Laws.$q$, $q$[{"conceptId": "cbvosp", "weight": 1}]$q$::jsonb, 4, $q$application$q$, 81, $q$low$q$, $q$light$q$, $q$[{"option": "A", "explanation": "Off by a factor of 8 \u2014 likely from mixing up units somewhere (forgetting to convert hours to seconds, or a slip in the mole-to-electron conversion).", "misconceptionId": "unit_conversion_error"}, {"option": "B", "explanation": "Off by a factor of 4 from the correct value \u2014 consistent with a partial unit-conversion or factor-of-3 electron-count error.", "misconceptionId": "unit_conversion_error"}, {"option": "C", "explanation": "Exactly double the correct answer \u2014 a common outcome of forgetting the '3 electrons per Al3+' factor and using 1.5 instead, or a factor-of-2 slip in the time conversion.", "misconceptionId": "arithmetic_slip"}]$q$::jsonb, $q$jamb_past_question$q$, 2001, $q$JAMB$q$, $q$What current in amperes will deposit 2.7g of aluminum in 2 hours? [Al = 27, F = 96500 C mol-1]$q$, $q$[{"label": "A", "text": "32", "isCorrect": false}, {"label": "B", "text": "16", "isCorrect": false}, {"label": "C", "text": "8", "isCorrect": false}, {"label": "D", "text": "4", "isCorrect": true}]$q$::jsonb, $q$D$q$, $q$Moles of Al = 2.7/27 = 0.1 mol. Since Al3+ + 3e- → Al, depositing 1 mol of Al takes 3 mol of electrons, so 0.1 mol Al takes 0.3 mol electrons. Charge needed = 0.3 × 96500 = 28,950 C. Convert 2 hours to seconds: 2 × 3600 = 7200s. Current = charge/time = 28,950/7200 ≈ 4A.$q$, $q$live$q$, $q$A: Off by a factor of 8 — likely from mixing up units somewhere (forgetting to convert hours to seconds, or a slip in the mole-to-electron conversion). B: Off by a factor of 4 from the correct value — consistent with a partial unit-conversion or factor-of-3 electron-count error. C: Exactly double the correct answer — a common outcome of forgetting the '3 electrons per Al3+' factor and using 1.5 instead, or a factor-of-2 slip in the time conversion.$q$),
($q$chemistry_0307$q$, $q$Chemistry$q$, $q$Chemical Equilibrium$q$, $q$Le Chatelier's Principle — Pressure & Temperature Effects$q$, $q$Answer a real JAMB 2001 question on Le Chatelier's Principle — Pressure & Temperature Effects.$q$, $q$[{"conceptId": "kzcd9t", "weight": 1}]$q$::jsonb, 4, $q$analysis$q$, 96, $q$low$q$, $q$light$q$, $q$[{"option": "B", "explanation": "Runs the temperature effect backwards \u2014 this reaction releases heat going forward, so raising temperature pushes the equilibrium toward the reactants, not toward more SO3.", "misconceptionId": "sign_error"}, {"option": "C", "explanation": "Vessel surface area isn't a variable that affects gas-phase equilibrium at all \u2014 likely confused with surface-area effects on reaction rate for solids.", "misconceptionId": "misunderstood_terminology"}, {"option": "D", "explanation": "A catalyst speeds up reaching equilibrium in both directions equally \u2014 it never shifts where the equilibrium actually sits, so it can't increase yield.", "misconceptionId": "misunderstood_terminology"}]$q$::jsonb, $q$jamb_past_question$q$, 2001, $q$JAMB$q$, $q$2SO2(g) + O2(g) ⇌ 2SO3(g). The yield of the reaction above is increased by$q$, $q$[{"label": "A", "text": "increasing the pressure of the system", "isCorrect": true}, {"label": "B", "text": "increasing the temperature of the system", "isCorrect": false}, {"label": "C", "text": "increasing the surface area of the vessel", "isCorrect": false}, {"label": "D", "text": "the addition of a catalyst to the system", "isCorrect": false}]$q$::jsonb, $q$A$q$, $q$Worth being precise here: pressure and temperature affect equilibrium differently. This reaction has 3 moles of gas on the left and 2 on the right, so increasing pressure shifts the equilibrium toward the side with fewer gas molecules (the product side), increasing the yield of SO3. That's a genuine shift in position — it does not change the equilibrium constant itself, which depends only on temperature. Since this reaction is exothermic forward, increasing temperature would actually shift equilibrium backward, reducing yield — so that's the wrong direction. A catalyst speeds up how fast equilibrium is reached but never changes the yield you end up with. 'Surface area of the vessel' isn't a real equilibrium variable at all.$q$, $q$live$q$, $q$B: Runs the temperature effect backwards — this reaction releases heat going forward, so raising temperature pushes the equilibrium toward the reactants, not toward more SO3. C: Vessel surface area isn't a variable that affects gas-phase equilibrium at all — likely confused with surface-area effects on reaction rate for solids. D: A catalyst speeds up reaching equilibrium in both directions equally — it never shifts where the equilibrium actually sits, so it can't increase yield.$q$),
($q$chemistry_0308$q$, $q$Chemistry$q$, $q$Electrolysis$q$, $q$Conductivity of Electrolytes$q$, $q$Answer a real JAMB 2001 question on Conductivity of Electrolytes.$q$, $q$[{"conceptId": "kwcqvs", "weight": 1}]$q$::jsonb, 2, $q$recall$q$, 37, $q$low$q$, $q$none$q$, $q$[{"option": "B", "explanation": "Runs the relationship backwards \u2014 fewer ions in solution means less, not more, charge-carrying capacity.", "misconceptionId": "sign_error"}, {"option": "C", "explanation": "Overstates the effect \u2014 diluting a solution reduces conductivity, but doesn't eliminate it entirely as long as some ions remain.", "misconceptionId": "overgeneralized_rule"}, {"option": "D", "explanation": "Assumes conductivity depends only on the identity of the electrolyte, ignoring that the actual number of charge carriers present matters too.", "misconceptionId": "missing_prerequisite"}]$q$::jsonb, $q$jamb_past_question$q$, 2001, $q$JAMB$q$, $q$As the concentration of an electrolyte reduces, the conductivity$q$, $q$[{"label": "A", "text": "decreases", "isCorrect": true}, {"label": "B", "text": "increases", "isCorrect": false}, {"label": "C", "text": "reduces to zero", "isCorrect": false}, {"label": "D", "text": "is unaffected", "isCorrect": false}]$q$::jsonb, $q$A$q$, $q$Fewer dissolved ions per unit volume means fewer charge carriers available to conduct current — so at this level, less concentrated means less conductive, in a straightforward direct relationship.$q$, $q$live$q$, $q$B: Runs the relationship backwards — fewer ions in solution means less, not more, charge-carrying capacity. C: Overstates the effect — diluting a solution reduces conductivity, but doesn't eliminate it entirely as long as some ions remain. D: Assumes conductivity depends only on the identity of the electrolyte, ignoring that the actual number of charge carriers present matters too.$q$),
($q$chemistry_0309$q$, $q$Chemistry$q$, $q$Energy Changes$q$, $q$Interpreting Enthalpy Sign and Magnitude$q$, $q$Answer a real JAMB 2001 question on Interpreting Enthalpy Sign and Magnitude.$q$, $q$[{"conceptId": "kshq1j", "weight": 1}]$q$::jsonb, 2, $q$recall$q$, 52, $q$low$q$, $q$moderate$q$, $q$[{"option": "B", "explanation": "Misreads \u0394H as a property split between the two reactants individually, rather than as the overall energy change of the whole reaction.", "misconceptionId": "misunderstood_terminology"}, {"option": "C", "explanation": "Same misreading \u2014 \u0394H describes the reaction's net energy change, not something each reactant separately 'contributes'.", "misconceptionId": "misunderstood_terminology"}, {"option": "D", "explanation": "Gets the sign backwards \u2014 a positive \u0394H means energy is absorbed (endothermic), not released.", "misconceptionId": "sign_error"}]$q$::jsonb, $q$jamb_past_question$q$, 2001, $q$JAMB$q$, $q$C(s) + 2S(g) → CS2, ΔH = 89 kJ mol-1. The chemical equation above implies that$q$, $q$[{"label": "A", "text": "89kJ of energy is absorbed", "isCorrect": true}, {"label": "B", "text": "each of carbon and sulphur has 89 kJ of energy", "isCorrect": false}, {"label": "C", "text": "both carbon and sulphur contribute 89kJ of energy", "isCorrect": false}, {"label": "D", "text": "89 kJ of energy is released", "isCorrect": false}]$q$::jsonb, $q$A$q$, $q$A positive ΔH means the reaction has to take in energy to proceed — that's the definition of endothermic. Carbon disulphide genuinely does have a positive standard enthalpy of formation in real data (around +89 kJ/mol), which matches what's given here.$q$, $q$live$q$, $q$B: Misreads ΔH as a property split between the two reactants individually, rather than as the overall energy change of the whole reaction. C: Same misreading — ΔH describes the reaction's net energy change, not something each reactant separately 'contributes'. D: Gets the sign backwards — a positive ΔH means energy is absorbed (endothermic), not released.$q$),
